package com.citacloud.app.views; import com.citacloud.app.models.Factura; import com.citacloud.app.security.*; import com.citacloud.app.services.FacturacionService; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.math.BigDecimal; import java.time.temporal.ChronoUnit; import java.util.*;
@Route(value="cuentas-por-cobrar",layout=MainLayout.class) @PageTitle("Cuentas por cobrar | CitaCloud") @PermitAll public class CuentasPorCobrarView extends VerticalLayout {public CuentasPorCobrarView(FacturacionService service){TenantUserDetails u=AuthService.getAuthenticatedUser();UUID empresa=u==null?null:u.getEmpresaId();List<Factura> facturas=empresa==null?List.of():service.listar(empresa).stream().filter(f->f.getSaldo().signum()>0).toList();BigDecimal total=facturas.stream().map(Factura::getSaldo).reduce(BigDecimal.ZERO,BigDecimal::add);setSizeFull();setPadding(true);add(new H2("Cuentas por cobrar"),new Paragraph("Total pendiente: "+total+" · Facturas pendientes: "+facturas.size()));Grid<Factura> grid=new Grid<>(Factura.class,false);grid.addColumn(Factura::getNumero).setHeader("FACTURA");grid.addColumn(f->f.getPaciente().getNombreCompleto()).setHeader("PACIENTE");grid.addColumn(Factura::getFecha).setHeader("FECHA");grid.addColumn(Factura::getTotal).setHeader("TOTAL");grid.addColumn(Factura::getMontoPagado).setHeader("PAGADO");grid.addColumn(Factura::getSaldo).setHeader("SALDO");grid.addColumn(f->ChronoUnit.DAYS.between(f.getFecha(),java.time.LocalDate.now())).setHeader("DÍAS PENDIENTES");grid.setItems(facturas);grid.setWidthFull();add(grid);}}
